-- Embroidery Studio schema — DRAFT v0.1 (2026-10-25)
-- MySQL 8.0+, InnoDB, utf8mb4.
--
-- Assumptions to reconcile before the first production migration:
--   * Existing table `users(id CHAR(36))`. Change type if the marketplace uses a different key (OQ-03).
--   * Purchases/subscriptions/entitlements live in existing marketplace tables and are
--     referenced here by opaque `entitlement_ref` strings (OQ-04).
--   * UUIDs are generated by the application (UUIDv7 recommended for index locality).
--
-- Table order respects FK dependencies. Circular FKs are added with ALTER at the end.

-- ---------------------------------------------------------------------------
-- Reference data
-- ---------------------------------------------------------------------------

CREATE TABLE design_machine_profiles (
  id                    CHAR(36)      PRIMARY KEY,
  owner_user_id         CHAR(36)      NULL COMMENT 'NULL = system preset',
  name                  VARCHAR(120)  NOT NULL,
  format_code           VARCHAR(20)   NOT NULL COMMENT 'Validated against app format registry: DST, PES, JEF',
  hoop_width_mm         DECIMAL(7,2)  NOT NULL,
  hoop_height_mm        DECIMAL(7,2)  NOT NULL,
  min_stitch_length_mm  DECIMAL(5,2)  NOT NULL DEFAULT 0.30,
  max_stitch_length_mm  DECIMAL(5,2)  NOT NULL DEFAULT 12.10,
  max_jump_length_mm    DECIMAL(6,2)  NULL,
  trim_jump_threshold_mm DECIMAL(6,2) NULL COMMENT 'Jumps longer than this get a trim',
  max_colors            SMALLINT UNSIGNED NULL,
  settings_json         JSON          NULL COMMENT 'Format/machine-specific extras',
  is_active             BOOLEAN       NOT NULL DEFAULT TRUE,
  created_at            DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at            DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  KEY idx_machine_profiles_owner (owner_user_id),
  CONSTRAINT fk_machine_profiles_owner FOREIGN KEY (owner_user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE design_thread_palette_items (
  id               CHAR(36)     PRIMARY KEY,
  brand            VARCHAR(80)  NOT NULL,
  color_code       VARCHAR(40)  NOT NULL,
  color_name       VARCHAR(120) NULL,
  hex_rgb          CHAR(7)      NOT NULL COMMENT '#RRGGBB',
  engine_mappings  JSON         NULL COMMENT '{ "<engine>": "<engine thread id>" }',
  license_reference VARCHAR(500) NULL COMMENT 'Thread charts may be licensed data',
  is_active        BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at       DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY uq_thread_brand_code (brand, color_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- Projects
-- ---------------------------------------------------------------------------

CREATE TABLE design_projects (
  id                   CHAR(36)     PRIMARY KEY,
  owner_user_id        CHAR(36)     NOT NULL,
  title                VARCHAR(200) NOT NULL,
  description          TEXT         NULL,
  visibility           ENUM('private','shared','marketplace') NOT NULL DEFAULT 'private',
  status               ENUM('draft','in_review','published','archived') NOT NULL DEFAULT 'draft',
  draft_document_json  JSON         NULL COMMENT 'Mutable autosave target; snapshotted into a version before any job',
  draft_schema_version INT UNSIGNED NULL,
  draft_revision       INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Optimistic concurrency for autosave',
  current_version_id   CHAR(36)     NULL,
  machine_profile_id   CHAR(36)     NULL,
  duplicated_from_project_id CHAR(36) NULL,
  deleted_at           DATETIME(3)  NULL COMMENT 'Soft delete; purge per retention policy',
  created_at           DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at           DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  KEY idx_projects_owner_updated (owner_user_id, updated_at),
  KEY idx_projects_status (status),
  CONSTRAINT fk_projects_owner   FOREIGN KEY (owner_user_id) REFERENCES users(id),
  CONSTRAINT fk_projects_profile FOREIGN KEY (machine_profile_id) REFERENCES design_machine_profiles(id),
  CONSTRAINT fk_projects_dup     FOREIGN KEY (duplicated_from_project_id) REFERENCES design_projects(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE design_project_versions (
  id                      CHAR(36)     PRIMARY KEY,
  project_id              CHAR(36)     NOT NULL,
  version_number          INT UNSIGNED NOT NULL,
  document_schema_version INT UNSIGNED NOT NULL,
  document_json           JSON         NOT NULL,
  document_sha256         CHAR(64)     NOT NULL,
  label                   VARCHAR(120) NULL COMMENT 'User checkpoint name',
  reason                  ENUM('manual','checkpoint','pre_job','submission','duplicate') NOT NULL DEFAULT 'manual',
  created_by              CHAR(36)     NOT NULL,
  created_at              DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY uq_project_version (project_id, version_number),
  KEY idx_versions_sha (project_id, document_sha256),
  KEY idx_project_versions_created (project_id, created_at),
  CONSTRAINT fk_project_versions_project FOREIGN KEY (project_id) REFERENCES design_projects(id),
  CONSTRAINT fk_project_versions_creator FOREIGN KEY (created_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE design_project_assets (
  id                CHAR(36)      PRIMARY KEY,
  project_id        CHAR(36)      NOT NULL,
  uploaded_by       CHAR(36)      NOT NULL,
  asset_kind        ENUM('svg','raster','font','other') NOT NULL,
  original_filename VARCHAR(255)  NULL COMMENT 'Display only; never used as a storage key',
  detected_mime     VARCHAR(100)  NOT NULL,
  storage_key       VARCHAR(1024) NOT NULL,
  sha256            CHAR(64)      NOT NULL,
  file_size_bytes   BIGINT UNSIGNED NOT NULL,
  scan_status       ENUM('pending','clean','rejected','error') NOT NULL DEFAULT 'pending',
  rights_id         CHAR(36)      NULL COMMENT 'Declared rights for this asset',
  created_at        DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY idx_assets_project (project_id),
  KEY idx_assets_scan (scan_status, created_at),
  CONSTRAINT fk_assets_project  FOREIGN KEY (project_id) REFERENCES design_projects(id),
  CONSTRAINT fk_assets_uploader FOREIGN KEY (uploaded_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE design_collaborators (
  id          CHAR(36)    PRIMARY KEY,
  project_id  CHAR(36)    NOT NULL,
  user_id     CHAR(36)    NOT NULL,
  role        ENUM('editor','viewer') NOT NULL,
  can_export  BOOLEAN     NOT NULL DEFAULT FALSE,
  invited_by  CHAR(36)    NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  revoked_at  DATETIME(3) NULL,
  UNIQUE KEY uq_collaborator (project_id, user_id),
  KEY idx_collaborator_user (user_id),
  CONSTRAINT fk_collab_project FOREIGN KEY (project_id) REFERENCES design_projects(id),
  CONSTRAINT fk_collab_user    FOREIGN KEY (user_id) REFERENCES users(id),
  CONSTRAINT fk_collab_inviter FOREIGN KEY (invited_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- Jobs and artifacts
-- ---------------------------------------------------------------------------

CREATE TABLE digitizing_jobs (
  id                   CHAR(36)     PRIMARY KEY,
  project_version_id   CHAR(36)     NOT NULL,
  input_artifact_id    CHAR(36)     NULL COMMENT 'stitch_data artifact consumed by simulate/validate/export',
  parent_job_id        CHAR(36)     NULL COMMENT 'Set when chained (e.g. digitizeIfMissing)',
  requested_by         CHAR(36)     NOT NULL,
  engine_name          VARCHAR(80)  NOT NULL,
  engine_version       VARCHAR(80)  NULL COMMENT 'Filled by worker with the exact version used',
  job_type             ENUM('digitize','simulate','validate','export') NOT NULL,
  target_format        VARCHAR(20)  NULL COMMENT 'Validated against app format registry',
  machine_profile_id   CHAR(36)     NULL,
  machine_profile_json JSON         NULL COMMENT 'Snapshot of the profile at request time',
  settings_json        JSON         NULL,
  status               ENUM('queued','running','succeeded','failed','cancelled') NOT NULL DEFAULT 'queued',
  cancel_requested     BOOLEAN      NOT NULL DEFAULT FALSE,
  progress             TINYINT UNSIGNED NOT NULL DEFAULT 0,
  attempt_count        SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  max_attempts         SMALLINT UNSIGNED NOT NULL DEFAULT 3,
  idempotency_key      VARCHAR(128) NOT NULL,
  error_code           VARCHAR(100) NULL,
  error_summary        VARCHAR(500) NULL COMMENT 'User-safe; detailed diagnostics go to restricted logs',
  heartbeat_at         DATETIME(3)  NULL,
  deadline_at          DATETIME(3)  NULL,
  started_at           DATETIME(3)  NULL,
  finished_at          DATETIME(3)  NULL,
  created_at           DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CHECK (progress <= 100),
  UNIQUE KEY uq_digitizing_idempotency (requested_by, idempotency_key),
  KEY idx_digitizing_queue (status, created_at),
  KEY idx_digitizing_version (project_version_id, created_at),
  KEY idx_digitizing_stuck (status, heartbeat_at),
  CONSTRAINT fk_jobs_version   FOREIGN KEY (project_version_id) REFERENCES design_project_versions(id),
  CONSTRAINT fk_jobs_parent    FOREIGN KEY (parent_job_id) REFERENCES digitizing_jobs(id),
  CONSTRAINT fk_jobs_requester FOREIGN KEY (requested_by) REFERENCES users(id),
  CONSTRAINT fk_jobs_profile   FOREIGN KEY (machine_profile_id) REFERENCES design_machine_profiles(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE design_artifacts (
  id                 CHAR(36)      PRIMARY KEY,
  project_version_id CHAR(36)      NOT NULL,
  job_id             CHAR(36)      NULL COMMENT 'NULL for source artifacts',
  artifact_type      ENUM('source','stitch_data','preview','machine_file','report') NOT NULL,
  format_code        VARCHAR(20)   NOT NULL DEFAULT '' COMMENT 'DST/PES/JEF for machine files, png/svg/json etc. otherwise; empty string if N/A',
  storage_key        VARCHAR(1024) NOT NULL,
  sha256             CHAR(64)      NOT NULL,
  file_size_bytes    BIGINT UNSIGNED NOT NULL,
  stitch_count       INT UNSIGNED  NULL,
  color_count        SMALLINT UNSIGNED NULL,
  trim_count         INT UNSIGNED  NULL,
  jump_count         INT UNSIGNED  NULL,
  width_mm           DECIMAL(9,3)  NULL,
  height_mm          DECIMAL(9,3)  NULL,
  engine_name        VARCHAR(80)   NULL,
  engine_version     VARCHAR(80)   NULL,
  validation_status  ENUM('pending','passed','warning','failed') NOT NULL DEFAULT 'pending',
  validation_report_artifact_id CHAR(36) NULL,
  deleted_at         DATETIME(3)   NULL,
  created_at         DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY uq_artifact_job_output (job_id, artifact_type, format_code) COMMENT 'Idempotent worker writes',
  KEY idx_artifact_version (project_version_id, artifact_type),
  KEY idx_artifact_job (job_id),
  CONSTRAINT fk_artifacts_version FOREIGN KEY (project_version_id) REFERENCES design_project_versions(id),
  CONSTRAINT fk_artifacts_job     FOREIGN KEY (job_id) REFERENCES digitizing_jobs(id),
  CONSTRAINT fk_artifacts_report  FOREIGN KEY (validation_report_artifact_id) REFERENCES design_artifacts(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE design_job_events (
  id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  job_id      CHAR(36)     NOT NULL,
  from_status VARCHAR(20)  NULL,
  to_status   VARCHAR(20)  NOT NULL,
  attempt     SMALLINT UNSIGNED NOT NULL,
  error_code  VARCHAR(100) NULL,
  message     VARCHAR(1000) NULL COMMENT 'No secrets, no raw engine dumps',
  worker_id   VARCHAR(120) NULL,
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY idx_job_events_job (job_id, id),
  CONSTRAINT fk_job_events_job FOREIGN KEY (job_id) REFERENCES digitizing_jobs(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE outbox_messages (
  id             BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  aggregate_type VARCHAR(60)  NOT NULL COMMENT 'e.g. digitizing_job',
  aggregate_id   CHAR(36)     NOT NULL,
  message_type   VARCHAR(80)  NOT NULL COMMENT 'e.g. job.queued',
  destination    VARCHAR(120) NOT NULL COMMENT 'Logical queue name',
  payload_json   JSON         NOT NULL,
  attempts       SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  last_error     VARCHAR(500) NULL,
  sent_at        DATETIME(3)  NULL,
  created_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY idx_outbox_unsent (sent_at, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- Rights, publication, licensing, audit
-- ---------------------------------------------------------------------------

CREATE TABLE design_rights (
  id                     CHAR(36)     PRIMARY KEY,
  project_id             CHAR(36)     NOT NULL,
  asset_id               CHAR(36)     NULL COMMENT 'NULL = rights for the design as a whole',
  declared_by            CHAR(36)     NOT NULL,
  rights_holder_user_id  CHAR(36)     NULL,
  rights_holder_name     VARCHAR(200) NULL COMMENT 'External holder when not a platform user',
  rights_type            ENUM('owned','licensed','commissioned','public_domain') NOT NULL,
  source_reference       VARCHAR(500) NULL,
  evidence_storage_key   VARCHAR(1024) NULL,
  license_terms_version  VARCHAR(80)  NULL,
  commercial_use_allowed BOOLEAN      NOT NULL DEFAULT FALSE,
  modification_allowed   BOOLEAN      NOT NULL DEFAULT FALSE,
  redistribution_allowed BOOLEAN      NOT NULL DEFAULT FALSE,
  verification_status    ENUM('declared','verified','rejected','disputed') NOT NULL DEFAULT 'declared',
  verified_by            CHAR(36)     NULL,
  verified_at            DATETIME(3)  NULL,
  created_at             DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY idx_design_rights_project (project_id),
  KEY idx_design_rights_asset (asset_id),
  CONSTRAINT fk_rights_project  FOREIGN KEY (project_id) REFERENCES design_projects(id),
  CONSTRAINT fk_rights_asset    FOREIGN KEY (asset_id) REFERENCES design_project_assets(id),
  CONSTRAINT fk_rights_declarer FOREIGN KEY (declared_by) REFERENCES users(id),
  CONSTRAINT fk_rights_holder   FOREIGN KEY (rights_holder_user_id) REFERENCES users(id),
  CONSTRAINT fk_rights_verifier FOREIGN KEY (verified_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE design_publications (
  id                    CHAR(36)     PRIMARY KEY,
  project_id            CHAR(36)     NOT NULL,
  project_version_id    CHAR(36)     NOT NULL COMMENT 'Exact version submitted',
  submitted_by          CHAR(36)     NOT NULL,
  status                ENUM('submitted','in_review','changes_requested','approved','rejected','withdrawn','taken_down') NOT NULL DEFAULT 'submitted',
  reviewer_user_id      CHAR(36)     NULL,
  decision_reason       VARCHAR(1000) NULL,
  marketplace_listing_ref VARCHAR(100) NULL COMMENT 'Existing marketplace listing id',
  submitted_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  decided_at            DATETIME(3)  NULL,
  published_at          DATETIME(3)  NULL,
  taken_down_at         DATETIME(3)  NULL,
  KEY idx_publications_project (project_id, submitted_at),
  KEY idx_publications_queue (status, submitted_at),
  CONSTRAINT fk_pub_project  FOREIGN KEY (project_id) REFERENCES design_projects(id),
  CONSTRAINT fk_pub_version  FOREIGN KEY (project_version_id) REFERENCES design_project_versions(id),
  CONSTRAINT fk_pub_submitter FOREIGN KEY (submitted_by) REFERENCES users(id),
  CONSTRAINT fk_pub_reviewer FOREIGN KEY (reviewer_user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE design_license_acceptances (
  id                    CHAR(36)     PRIMARY KEY,
  user_id               CHAR(36)     NOT NULL,
  license_terms_version VARCHAR(80)  NOT NULL,
  project_id            CHAR(36)     NULL COMMENT 'NULL for subscription-wide acceptance',
  entitlement_type      ENUM('purchase','subscription','creator_terms') NOT NULL,
  entitlement_ref       VARCHAR(100) NULL COMMENT 'Existing marketplace purchase/subscription id',
  accepted_at           DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  client_ip_hash        CHAR(64)     NULL,
  KEY idx_license_user (user_id, accepted_at),
  KEY idx_license_entitlement (entitlement_ref),
  CONSTRAINT fk_license_user    FOREIGN KEY (user_id) REFERENCES users(id),
  CONSTRAINT fk_license_project FOREIGN KEY (project_id) REFERENCES design_projects(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE design_export_events (
  id               BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  artifact_id      CHAR(36)     NOT NULL,
  user_id          CHAR(36)     NOT NULL,
  decision         ENUM('allowed','denied') NOT NULL,
  basis            ENUM('owner','collaborator','staff','purchase','subscription','none') NOT NULL,
  reason_code      VARCHAR(80)  NULL,
  entitlement_ref  VARCHAR(100) NULL,
  license_acceptance_id CHAR(36) NULL,
  url_expires_at   DATETIME(3)  NULL,
  client_ip_hash   CHAR(64)     NULL,
  user_agent       VARCHAR(300) NULL,
  correlation_id   VARCHAR(64)  NULL,
  created_at       DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY idx_export_artifact (artifact_id, created_at),
  KEY idx_export_user (user_id, created_at),
  CONSTRAINT fk_export_artifact FOREIGN KEY (artifact_id) REFERENCES design_artifacts(id),
  CONSTRAINT fk_export_user     FOREIGN KEY (user_id) REFERENCES users(id),
  CONSTRAINT fk_export_license  FOREIGN KEY (license_acceptance_id) REFERENCES design_license_acceptances(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- Circular / late foreign keys
-- ---------------------------------------------------------------------------

ALTER TABLE design_projects
  ADD CONSTRAINT fk_projects_current_version
  FOREIGN KEY (current_version_id) REFERENCES design_project_versions(id);

ALTER TABLE digitizing_jobs
  ADD CONSTRAINT fk_jobs_input_artifact
  FOREIGN KEY (input_artifact_id) REFERENCES design_artifacts(id);

ALTER TABLE design_project_assets
  ADD CONSTRAINT fk_assets_rights
  FOREIGN KEY (rights_id) REFERENCES design_rights(id);
